<?php declare(strict_types=1); require_once __DIR__.'/bootstrap.php';
try{verify_csrf($_POST['csrf']??null);$w=$_SESSION['wizard']??null;if(!$w)throw new RuntimeException('Upload session expired. Please upload again.');$fields=array_values(array_filter($_POST['rules']??[],fn($v)=>is_string($v)&&trim($v)!==''));if(!$fields)throw new RuntimeException('Select at least one comparison field.');$mode=in_array($_POST['mode']??'', ['smart','exact'],true)?$_POST['mode']:'smart';$ma=[];$mb=[];foreach($w['headers_a'] as $i=>$h)if(in_array($h,$fields,true))$ma[$h]=$i;foreach($w['headers_b'] as $i=>$h)if(in_array($h,$fields,true))$mb[$h]=$i;if(count($ma)!==count($fields)||count($mb)!==count($fields))throw new RuntimeException('Selected fields are not present in both files.');$c=new App\Comparison(new App\ExcelReader(),new App\MatchingEngine(new App\Normalizer()),new App\DuplicateDetector(new App\MatchingEngine(new App\Normalizer())),new App\Normalizer());$res=$c->run($w['file_a'],$w['file_b'],$ma,$mb,$fields,$mode);$h=(new App\History())->save(['file_a'=>$w['name_a'],'file_b'=>$w['name_b'],'mode'=>$mode,'rules'=>$fields,'summary'=>array_intersect_key($res,array_flip(['totalA','totalB','matched','modified','missingA','missingB','duplicate','invalid','percentage']))]);$_SESSION['result']=$res;$_SESSION['meta']=['hash'=>$h,'file_a'=>$w['name_a'],'file_b'=>$w['name_b'],'rules'=>$fields,'mode'=>$mode];unset($_SESSION['wizard']);redirect('result.php');}catch(Throwable $e){(new App\Logger())->error($e->getMessage(),['trace'=>$e->getTraceAsString()]);$_SESSION['error']=$e->getMessage();redirect('mapping.php');}
